INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(10401, '1 Chronicles 27:33', '1 Chronicles', 27, 33, '&nbsp;اخى‌تُفل د بادشاه مشير وو او حوسى ارکياۍ د بادشاه ملګرے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10402, '1 Chronicles 27:34', '1 Chronicles', 27, 34, '&nbsp;د اخى‌تُفل د مرګ نه پس، ابياتار او د بناياه زوئ يهويدع مشيران جوړ شول. يوآب د شاهى فوج مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10403, '1 Chronicles 28:1', '1 Chronicles', 28, 1, '&nbsp;داؤد بادشاه د بنى اِسرائيلو ټولو آفسرانو له حُکم ورکړو چې په يروشلم کښې راغونډ شئ. نو د قبيلو ټول آفسران، هغه آفسران چا چې د بادشاهۍ اِنتظام کولو، د فوجى ډلو مشران، د بادشاه او د هغۀ د زامنو د جائيداد او د څاروو ذمه وار کسان، د محل ټول آفسران، تکړه فوجيان او نور بهادر سړى په يروشلم کښې راغونډ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10404, '1 Chronicles 28:2', '1 Chronicles', 28, 2, '&nbsp;داؤد د هغوئ په وړاندې ودرېدلو او تقرير يې ورته وکړو، ”زما خلقو او زما وروڼو، ما ته غوږ ونيسئ. ما دا اراده کړې وه چې د مالِک خُدائ د لوظ صندوق دپاره د آرام ځائ يعنې د مالِک خُدائ زمونږ د خُدائ پاک د پښو چوکۍ جوړه کړم. ما د هغۀ دپاره د يو کور د جوړولو تيارے کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10405, '1 Chronicles 28:3', '1 Chronicles', 28, 3, '&nbsp;خو خُدائ پاک ما ته وفرمائيل چې تۀ به زما د نوم دپاره يو کور نۀ جوړوې، ځکه چې تۀ يو جنګيالے يې او وينه دې توئ کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10406, '1 Chronicles 28:4', '1 Chronicles', 28, 4, '&nbsp;مالِک خُدائ د بنى اِسرائيلو خُدائ پاک زما د پلار د مکمل خاندان نه زۀ خوښ کړے يم چې د تل دپاره په بنى اِسرائيلو حکومت وکړم. هغۀ د مشرۍ کولو دپاره د يهوداه قبيله خوښه کړه او د يهوداه نه يې زما د پلار خاندان خوښ کړو. دا د هغۀ خوښه وه چې د خپلو وروڼو نه يې زۀ خوښ کړم او په ټولو بنى اِسرائيلو يې بادشاه جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10407, '1 Chronicles 28:5', '1 Chronicles', 28, 5, '&nbsp;هغۀ ما له ډېر زامن راکړل او د هغه ټولو نه يې سليمان خوښ کړو چې د مالِک خُدائ په بادشاهۍ يعنې په ټولو بنى اِسرائيلو باندې حکومت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10408, '1 Chronicles 28:6', '1 Chronicles', 28, 6, '&nbsp;مالِک خُدائ ما ته وفرمائيل چې ستا زوئ سليمان هغه څوک دے چې هغه به زما کور جوړ کړى. هغه ما د دې دپاره خوښ کړے دے چې زما زوئ وى او زۀ به د هغۀ پلار يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10409, '1 Chronicles 28:7', '1 Chronicles', 28, 7, '&nbsp;کۀ هغه زما ټول قانون او حُکمونه هم هغه شان منى لکه څنګه يې چې نن منى نو زۀ به د هغۀ بادشاهى د همېشه دپاره قائمه وساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10410, '1 Chronicles 28:8', '1 Chronicles', 28, 8, '&nbsp;نو اوس زما خلقو، زمونږ د خُدائ پاک او د مالِک خُدائ د خلقو بنى اِسرائيلو د غونډې په مخکښې زۀ تاسو ته وايم چې هغه هر څۀ هم هغه شان پوره پوره منئ چې مالِک خُدائ زمونږ خُدائ پاک د هغې حُکم راکړے دے، نو چې دا ښۀ مُلک ستاسو ميراث وى او چې د همېشه دپاره يې خپلو راتلونکو نسلونو ته منتقل کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10411, '1 Chronicles 28:9', '1 Chronicles', 28, 9, '&nbsp;او هغۀ سليمان ته وفرمائيل، ”زما زويه، زۀ تا ته وايم چې د پلار خُدائ پاک وپېژنه او د زړۀ د اخلاصه او د خپلې مرضۍ سره د هغۀ خِدمت کوه. هغه زمونږ ټول فکرونه او خواهشونه معلوموى. کۀ تۀ د هغۀ طلب کوې نو پېدا به يې کړې، خو کۀ تۀ د هغۀ نه اوړې، نو هغه به تا د تل دپاره پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10412, '1 Chronicles 28:10', '1 Chronicles', 28, 10, '&nbsp;تۀ په دې پوهه شه چې مالِک خُدائ تۀ د هغۀ د مقدس کور جوړولو دپاره خوښ کړے يې. نو تکړه شه او دا کار وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10413, '1 Chronicles 28:11', '1 Chronicles', 28, 11, '&nbsp;داؤد سليمان ته د مالِک خُدائ د کور د ټولو عمارتُونو، د برنډو، د ګودام د کوټو او نورو ټولو کوټو او د زيات مقدس ځائ نقشه وښودله، چرته چې د ګناه دپاره کفاره ادا کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10414, '1 Chronicles 28:12', '1 Chronicles', 28, 12, '&nbsp;د هغۀ په ذهن کښې چې د دربارونو او د دې نه ګېرچاپېره کوټو او د مالِک خُدائ د کور د سامان دپاره د ګودامونو او مالِک خُدائ ته د وقف شوو تُحفو کومه نقشه وه نو هغه يې هم ورته وښودله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10415, '1 Chronicles 28:13', '1 Chronicles', 28, 13, '&nbsp;داؤد هغۀ ته د اِمامانو او ليويانو د ذمه وارو ادا کولو اِنتظام، د مالِک خُدائ د کور د کار کولو او د کور د ټولو لوښو خيال ساتلو طريقه هم وښودله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10416, '1 Chronicles 28:14', '1 Chronicles', 28, 14, '&nbsp;هغۀ ورته دا طريقه هم وښودله چې د لوښو د جوړولو دپاره به څومره سپين زر او سرۀ زر استعماليږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10417, '1 Chronicles 28:15', '1 Chronicles', 28, 15, '&nbsp;يعنې هرې يوې ډيوې او ډيوټ د جوړولو دپاره،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10418, '1 Chronicles 28:16', '1 Chronicles', 28, 16, '&nbsp;د سپينو زرو د مېزونو د جوړولو او د سرو زرو د هر يو مېز دپاره چې په دې باندې خُدائ پاک ته پېش کړے شوې روټۍ پراته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10419, '1 Chronicles 28:17', '1 Chronicles', 28, 17, '&nbsp;هغۀ ورته دا هم ووئيل چې د درې غاښو، جامونو او منګو په جوړولو کښې څومره سوچه سرۀ زر او د لوښو په جوړولو کښې به څومره سپين زر او سرۀ زر استعماليږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10420, '1 Chronicles 28:18', '1 Chronicles', 28, 18, '&nbsp;او د هغه قربان‌ګاه د جوړولو دپاره څومره سوچه سرۀ زر چې په هغې باندې خوشبوئى سوزولے شوه او د وزرو والا هغه مخلوق د جوړولو دپاره چې د هغې وزر د مالِک خُدائ د لوظ صندوق دپاسه خوارۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10421, '1 Chronicles 28:19', '1 Chronicles', 28, 19, '&nbsp;داؤد بادشاه وفرمائيل، ”دا ټول تفصيل په هغه نقشه کښې ليکلے شوے دے چې مالِک خُدائ په خپله ما له راکړې وه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10422, '1 Chronicles 28:20', '1 Chronicles', 28, 20, '&nbsp;داؤد بادشاه خپل زوئ سليمان ته وفرمائيل، ”تکړه شه او اراده مضبوطه کړه. کار شروع کړه او چې ونۀ يرېږې او نه بې‌حوصلې شې. مالِک خُدائ زما خُدائ پاک به ستا مل وى. هغه به تا نۀ پرېږدى، خو هغه به تر هغې پورې تا سره وى چې د هغۀ يعنې د مالِک خُدائ د کور کار ختم شوے نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10423, '1 Chronicles 28:21', '1 Chronicles', 28, 21, '&nbsp;اِمامانو او ليويانو ته ذمه وارۍ حواله شوې دى چې د مالِک خُدائ په هغه کور کښې يې وکړى. د هر قِسم مهارت کاريګران د زړۀ نه غواړى چې ستا مدد وکړى او ټول خلق او د هغوئ مشران ستا د حُکم لاندې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10424, '1 Chronicles 29:1', '1 Chronicles', 29, 1, '&nbsp;داؤد بادشاه ټولې غونډې ته وفرمائيل، ”زما زوئ سليمان هغه څوک دے چې خُدائ پاک خوښ کړے دے، خو هغه لا هلک او ناتجربه‌کاره دے. کوم کار چې کېدونکے دے هغه ډېر لوئ دے، ځکه چې دا د انسانانو محل نۀ دے بلکې د مالِک خُدائ، خُدائ پاک کور دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10425, '1 Chronicles 29:2', '1 Chronicles', 29, 2, '&nbsp;ما د خپل خُدائ پاک د کور د سرو زرو، سپينو زرو، پيتلو، اوسپنې، لرګى، د اونيکس کاڼو او جواهراتو، د ښائسته کاڼو ټوکړو او د سنګِ مرمر د مِقدار تيارولو هر کوشش کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10426, '1 Chronicles 29:3', '1 Chronicles', 29, 3, '&nbsp;د دې هر څۀ نه علاوه، چې ما د مخکښې نه تيار کړى دى د خُدائ پاک د کور سره زما د مينې په وجه ما خپل سپين زر او سرۀ زر هم ورکړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10427, '1 Chronicles 29:4', '1 Chronicles', 29, 4, '&nbsp;د مالِک خُدائ د کور په دېوالونو باندې د سرو زرو او سپينو زرو پترو خېژولو دپاره ما د اوفير د سلو ټنو نه زيات سرۀ زر او تقريباً دوه سوه او څلوېښت ټنه سوچه سپين زر هم ورکړى دى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10428, '1 Chronicles 29:5', '1 Chronicles', 29, 5, '&nbsp;او د هغه ټولو څيزونو دپاره مې دا ورکړى دى چې ماهِر کاريګران به يې جوړوى. نو اوس داسې نور څوک شته چې مالِک خُدائ له نذرانې ورکړى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10429, '1 Chronicles 29:8', '1 Chronicles', 29, 8, '&nbsp;د چا سره چې قيمتى کاڼى وُو نو هغه يې د مالِک خُدائ د کور د خزانې دپاره ورکړل، چې د هغې اِنتظام د جيرسون قبيلې د ليوى قبيلې يحى‌ايل کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10430, '1 Chronicles 29:9', '1 Chronicles', 29, 9, '&nbsp;خلقو د زړۀ د اخلاصه څيزونه ورکول او هغوئ په دې خوشحاله وُو چې څومره زيات يې ورکړى دى. داؤد بادشاه هم ډېر زيات خوشحاله وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10431, '1 Chronicles 29:10', '1 Chronicles', 29, 10, '&nbsp;هلته د ټولې غونډې په مخکښې داؤد د مالِک خُدائ ثناء صِفت وکړو. هغۀ وفرمائيل، ”زمونږ د پلار نيکۀ يعقوب مالِک خُدائ، خُدائ پاکه، ستا ثناء صِفت دې د همېشه دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10432, '1 Chronicles 29:11', '1 Chronicles', 29, 11, '&nbsp;تۀ لوئ او طاقتور، د شان او شوکت والا او عزتمند يې. په زمکه او آسمان کښې هر څۀ ستا دى او اے مالِک خُدايه، تۀ په هر څۀ باندې عظيم بادشاه او حکمران يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10433, '1 Chronicles 29:12', '1 Chronicles', 29, 12, '&nbsp;عزت او دولت ستا نه راځى، تۀ په خپل طاقت او قوت سره په هر څۀ حکومت کوې، او تۀ کولے شې چې هر څوک لوئ او طاقتور کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10434, '1 Chronicles 29:13', '1 Chronicles', 29, 13, '&nbsp;اوس زمونږ خُدايه پاکه، مونږ ستا شُکر کوُو او مونږ ستا د جلال نه د ډک نوم ثناء صِفت کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10435, '1 Chronicles 29:14', '1 Chronicles', 29, 14, '&nbsp;خو بيا هم په حقيقت کښې زۀ او زما خلق تا له هيڅ هم نۀ شُو درکولے، ځکه چې هر يو څيز ستا د طرف نه نعمت دے او مونږ صِرف تا له هغه څۀ واپس درکړى دى چې څۀ ستا وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10436, '1 Chronicles 29:15', '1 Chronicles', 29, 15, '&nbsp;مالِکه خُدايه، تا ته پته ده چې زمونږ د پلار نيکۀ په شان مونږ خپل ژوند د مسافرو په شان په يو ځائ بل ځائ کښې تېر کړے دے، زمونږ ژوند د تېرېدونکى سورى په شان فانى دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10437, '1 Chronicles 29:16', '1 Chronicles', 29, 16, '&nbsp;مالِکه خُدايه، زمونږ خُدايه پاکه، مونږ دا ټول دولت ستا د کور د جوړولو دپاره راوړے دے چې ستا د نوم درناوے وشى، خو دا ټول دولت ستا نه راغلے وو او دا ټول ستا دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10438, '1 Chronicles 29:17', '1 Chronicles', 29, 17, '&nbsp;ما ته پته ده چې تۀ د هر چا زړۀ معلوموې او د خلقو په صداقت خوشحاليږى. په روغ نېت او خلوص سره ما دا هر څۀ تا له درکړى دى او ما ته پته لګېدلې ده چې کوم خلق دلته راغونډ شوى دى هغوئ تا له څومره په شوق او خوشحالۍ سره نذرانې راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10439, '1 Chronicles 29:18', '1 Chronicles', 29, 18, '&nbsp;مالِکه خُدايه، زمونږ د پلار نيکۀ اِبراهيم، اِسحاق او يعقوب خُدايه پاکه، ستا د خپلو خلقو په زړۀ کښې تا سره دا مينه د همېشه دپاره مضبوطه وساته او د هغوئ زړونه وفادار وساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10440, '1 Chronicles 29:19', '1 Chronicles', 29, 19, '&nbsp;زما د زوئ سليمان په زړۀ کښې دا جذبه واچوه چې ستا ټول حُکمونه ومنى او هغه کور جوړ کړى چې د کومې دپاره ما دا تيارے کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10441, '1 Chronicles 29:20', '1 Chronicles', 29, 20, '&nbsp;بيا داؤد ټولې قبيلې له حُکم ورکړو، ”د مالِک خُدائ ستاسو د خُدائ پاک ثناء صِفت وکړئ.“ نو ټولې غونډې د مالِک خُدائ، د خپل پلار نيکۀ د خُدائ پاک ثناء صِفت وکړو او هغوئ لاندې ټيټ شول او مالِک خُدائ او بادشاه له يې عزت ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10442, '1 Chronicles 29:21', '1 Chronicles', 29, 21, '&nbsp;په ورپسې ورځ هغوئ د قربانۍ په توګه ځناور حلال کړل، مالِک خُدائ ته يې وقف کړل او بيا يې خلقو له ورکړل چې وې خورى. د دې نه علاوه، هغوئ يو زر غوَيى، يو زر ګډان او يو زر ګډُورى هم حلال کړل، چې په قربان‌ګاه باندې يې پوره وسوزول. هغوئ د ميو نذرانې هم راوړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10443, '1 Chronicles 29:22', '1 Chronicles', 29, 22, '&nbsp;چې هغوئ د مالِک خُدائ په حضور کښې خوراک څښاک وکړو نو په هغه ورځ هغوئ ډېر خوشحاله وُو. هغوئ په دوېم ځل سليمان بادشاه جوړ کړو. هغوئ د مالِک خُدائ په نوم سليمان د بادشاه په توګه او صدوق د اِمام په توګه مقرر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10444, '1 Chronicles 29:23', '1 Chronicles', 29, 23, '&nbsp;نو سليمان د خپل پلار داؤد نه پس په هغه تخت باندې کښېناستو کوم چې مالِک خُدائ قائم کړے وو. هغه يو کامياب بادشاه وو او د بنى اِسرائيلو ټول قوم هغه منلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10445, '1 Chronicles 29:24', '1 Chronicles', 29, 24, '&nbsp;ټولو آفسرانو، فوجيانو او تر دې پورې چې د داؤد نورو زامنو هم دا لوظ وکړو چې د سليمان بادشاه وفادار به وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10446, '1 Chronicles 29:25', '1 Chronicles', 29, 25, '&nbsp;مالِک خُدائ سليمان د ټول قوم په نظر کښې عزتمند کړو او د هغه نورو ټولو بادشاهانو نه يې زيات شان او شوکت ورکړو چې کوم به په بنى اِسرائيلو بادشاهى کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10447, '1 Chronicles 29:26', '1 Chronicles', 29, 26, '&nbsp;نو د يَسى زوئ داؤد په ټولو بنى اِسرائيلو باندې بادشاهى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10448, '1 Chronicles 29:27', '1 Chronicles', 29, 27, '&nbsp;هغۀ څلوېښتو کالو پورې بادشاهى کوله. هغۀ په حبرون کښې اووۀ کاله او په يروشلم کښې درې دېرش کاله بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10449, '1 Chronicles 29:28', '1 Chronicles', 29, 28, '&nbsp;هغه يو عزتمند او مالدار سړے وو او ښۀ په پوخ عُمر کښې مړ شو او د هغۀ زوئ سليمان د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10450, '1 Chronicles 29:29', '1 Chronicles', 29, 29, '&nbsp;د داؤد بادشاه تاريخ د اول نه واخله تر آخره پورې د دې درېو پېغمبرانو په کتابونو کښې ليکلے شوے دے، سموئيل، ناتن او جاد.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10451, '1 Chronicles 29:30', '1 Chronicles', 29, 30, '&nbsp;د تاريخ دا کتابونه وائى چې هغۀ څنګه حکومت وکړو او هغه څومره طاقتور وو او هغه هر څۀ چې په هغۀ، بنى اِسرائيلو او ګېرچاپېره بادشاهتونو شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10452, '2 Chronicles 1:1', '2 Chronicles', 1, 1, '&nbsp;د داؤد بادشاه زوئ سليمان خپله بادشاهى ښۀ مضبوطه کړه او مالِک خُدائ د هغۀ خُدائ پاک د هغۀ مل وو او هغه يې ډېر طاقتور کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10453, '2 Chronicles 1:2', '2 Chronicles', 1, 2, '&nbsp;سليمان بادشاه هغه ټولو آفسرانو له چې د زرو سړو او سلو سړو د ډلو مشران وُو، د حکومت ټولو آفسرانو او کورَنو ټولو مشرانو له حُکم ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10454, '2 Chronicles 1:3', '2 Chronicles', 1, 3, '&nbsp;هغوئ ته يې دا وفرمائيل چې د هغۀ سره په جبعون کښې د عبادت ځائ ته لاړ شى. هغوئ هلته ځکه لاړل چې دا هغه ځائ وو چرته چې د مالِک خُدائ د حضور خېمه لګېدلې وه، کومه چې د مالِک خُدائ خِدمت کوونکى موسىٰ په بيابان کښې جوړه کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10455, '2 Chronicles 1:4', '2 Chronicles', 1, 4, '&nbsp;داؤد د لوظ صندوق د مخکښې نه د قِريَت‌يعريم نه هغه خېمې ته راوړے وو چې کومه يې د دې دپاره په يروشلم کښې جوړه کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10456, '2 Chronicles 1:5', '2 Chronicles', 1, 5, '&nbsp;خو د زېړو کومه قربان‌ګاه چې د حُور نمسى او د اورى زوئ بضلى‌اېل جوړه کړې وه هغه هلته په جبعون کښې د مالِک خُدائ د مقدسې خېمې په مخکښې پرته وه. سليمان بادشاه او ټولو خلقو هلته مالِک خُدائ ته سوال وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10457, '2 Chronicles 1:6', '2 Chronicles', 1, 6, '&nbsp;سليمان د مالِک خُدائ په حضور کښې قربان‌ګاه ته وختلو، کومه چې د مالِک خُدائ د مقدسې خېمې په مخکښې پرته وه او په هغې باندې يې يو زر سوزېدونکې نذرانې پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10458, '2 Chronicles 1:7', '2 Chronicles', 1, 7, '&nbsp;په هغه شپه خُدائ پاک سليمان ته څرګند شو او ورته يې وفرمائيل، ”چې څۀ غواړې نو وې غواړه چې زۀ يې درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10459, '2 Chronicles 1:8', '2 Chronicles', 1, 8, '&nbsp;سليمان ورته وفرمائيل، ”تا زما پلار داؤد ته همېشه لويه مينه ښودلې ده او اوس دې زۀ د هغۀ نه پس بادشاه جوړ کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10460, '2 Chronicles 1:9', '2 Chronicles', 1, 9, '&nbsp;اے مالِکه خُدايه پاکه، هغه وعده پوره کړه چې زما د پلار سره دې کړې ده. تا زۀ په هغه خلقو بادشاه جوړ کړے يم چې څوک د زمکې د شګو په شان ډېر دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10461, '2 Chronicles 1:10', '2 Chronicles', 1, 10, '&nbsp;نو ما له پوهه او حِکمت راکړه چې هغوئ په سمه لار باندې بوځم. څوک داسې شته چې ستا په دې لوئ قوم باندې حکومت وکړى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10462, '2 Chronicles 1:11', '2 Chronicles', 1, 11, '&nbsp;خُدائ پاک سليمان ته وفرمائيل، ”تا جائيداد، دولت، عزت، يا د هغه خلقو مرګ نۀ دے غوښتلے چې ستا نه نفرت کوى او د اوږد عُمر سوال دې هم نۀ دے کړے، خو تا د حِکمت او پوهې سوال کړے دے چې زما په هغه خلقو باندې حکومت وکړې چې په چا باندې ما بادشاه جوړ کړې يې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10463, '2 Chronicles 1:12', '2 Chronicles', 1, 12, '&nbsp;نو ځکه زۀ به تا له حِکمت او پوهه درکړم. او د دې نه علاوه، زۀ به تا له دومره دولت، خزانې او عزت درکړم چې نۀ به د دې نه مخکښې يو بادشاه ته مِلاو شوى وى او نۀ به وروستو چا ته کله هم مِلاو شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10464, '2 Chronicles 1:13', '2 Chronicles', 1, 13, '&nbsp;نو سليمان په جبعون کښې د عبادت د ځائ نه لاړو، چرته چې د مالِک خُدائ د حضور خېمه وه او يروشلم ته راواپس شو. هلته هغۀ په اِسرائيل حکومت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10465, '2 Chronicles 1:14', '2 Chronicles', 1, 14, '&nbsp;هغۀ هلته د څوارلسو سوو جنګى ګاډو او دولس زرو په آسونو سوارو کسانو يو لښکر جوړ کړو، د هغوئ څۀ کسان يې په يروشلم کښې وساتل او باقى نور يې په مختلفو ښارونو کښې کښېنول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10466, '2 Chronicles 1:15', '2 Chronicles', 1, 15, '&nbsp;د هغۀ د بادشاهۍ په دوران کښې سپين زر او سرۀ زر په يروشلم کښې د کاڼو په شان عام شول او دِيار دومره زيات وُو لکه چې د غرونو په لمنو کښې بې‌شمېره چنارونه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10467, '2 Chronicles 2:1', '2 Chronicles', 2, 1, '&nbsp;سليمان فېصله وکړه چې يو کور جوړ کړى چرته به چې د مالِک خُدائ د نوم عبادت کيږى او د خپل ځان دپاره يو شاهى محل هم جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10468, '2 Chronicles 2:2', '2 Chronicles', 2, 2, '&nbsp;هغۀ اويا زره سړى د سامان راوړلو او اتيا زره سړى يې د غرونو نه د کاڼو د راويستلو دپاره مقرر کړل. درې زره او شپږ سوه داسې نور سړى وُو چې د کار مشرى يې کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10469, '2 Chronicles 2:3', '2 Chronicles', 2, 3, '&nbsp;سليمان د صور بادشاه حيرام له يو پېغام ولېږلو چې، ”ما له د دِيار لرګى راولېږه لکه څنګه چې تا زما پلار داؤد له لېږلى وُو چې کله هغۀ محل جوړولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10470, '2 Chronicles 2:4', '2 Chronicles', 2, 4, '&nbsp;زۀ د مالِک خُدائ زما د خُدائ پاک د نوم د درناوى دپاره يو کور جوړوم. دا به يو مخصوص ځائ وى چرته به چې د هغۀ په مخکښې خوشبوئى سوزولے شى، د قربانۍ خاص روټۍ پېش کولے شى او چې په هر سحر او ماښام، د سبت په ورځ، د نوې مياشتې په اخترونو او د مالِک خُدائ زمونږ د خُدائ پاک په نورو مقررو اخترونو باندې سوزېدونکې نذرانې پېش کولے شى. هغۀ اِسرائيل له حُکم ورکړے دے چې دا کار به د همېشه دپاره کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10471, '2 Chronicles 2:5', '2 Chronicles', 2, 5, '&nbsp;زۀ چې کوم کور جوړوم نو هغه به عظيم کور وى، ځکه چې زمونږ خُدائ پاک د نورو ټولو معبودانو نه لوئ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10472, '2 Chronicles 2:6', '2 Chronicles', 2, 6, '&nbsp;خو په حقيقت کښې بيا هم څوک د خُدائ پاک دپاره کور نۀ شى جوړولے، ځکه چې په لويو آسمانونو کښې هغه نۀ شى ځائېدلے. نو زۀ څوک يم چې د هغۀ دپاره يو کور جوړ کړم، بغېر د دې نه چې يو ځائ جوړ کړم چې د هغۀ په وړاندې په کښې نذرانې پېش کيږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10473, '2 Chronicles 2:7', '2 Chronicles', 2, 7, '&nbsp;نو ما له يو سړے راولېږه چې په نقش نګارۍ کښې، د سرو زرو، سپينو زرو، زېړو او اوسپنې په کار کښې او د آسمانى رنګ، کاسنى او د سور رنګ کپړه جوړولو کښې ماهِر وى. هغه به د يهوداه او يروشلم کاريګرو سره کار کوى کوم چې زما پلار داؤد خوښ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10474, '2 Chronicles 2:8', '2 Chronicles', 2, 8, '&nbsp;ما ته پته ده چې ستاسو د لرګو وهونکى سړى ډېر تکړه دى، نو ما له د لبنان نه د دِيار، سبر ونې او صُندل لرګى راولېږه. زما سړى به ستاسو د سړو مدد کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10475, '2 Chronicles 2:9', '2 Chronicles', 2, 9, '&nbsp;چې ډېر زيات لرګى تيار کړى، ځکه چې زما د خُدائ پاک د کوم کور د جوړولو اراده ده هغه به لوئ او بې‌مثاله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10476, '2 Chronicles 2:10', '2 Chronicles', 2, 10, '&nbsp;ګوره، ستا د کاريګرانو په مزدورۍ کښې به دوه زره ټنه غنم او دوه زره ټنه اوربشې، څلور لاکه ليټره مے او څلور لاکه ليټره د زيتُونو تېل درولېږم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10477, '2 Chronicles 2:11', '2 Chronicles', 2, 11, '&nbsp;د صور بادشاه حيرام سليمان له په جواب کښې يو خط ولېږلو. هغۀ ورته ليکلى وُو، ”مالِک خُدائ د خپلو خلقو سره مينه کوى نو په دې وجه هغۀ تۀ د هغوئ بادشاه جوړ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10478, '2 Chronicles 2:12', '2 Chronicles', 2, 12, '&nbsp;د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک ثناء صِفت دې وى، چې د آسمان او زمکې پېدا کوونکے دے. هغۀ داؤد بادشاه له يو هوښيار زوئ ورکړے دے، چې د پوهې او مهارت خاوند دے، چې اوس د هغۀ منصوبه دا ده چې د مالِک خُدائ دپاره يو کور او د خپل ځان دپاره يو محل جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10479, '2 Chronicles 2:13', '2 Chronicles', 2, 13, '&nbsp;زۀ تا له يو قابل او تکړه اُستاذ درلېږم چې د هغۀ نوم حيرام دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10480, '2 Chronicles 2:14', '2 Chronicles', 2, 14, '&nbsp;د هغۀ مور د دان د قبيلې وه او د هغۀ پلار د صور اصلى اوسېدونکے وو. هغه د سرو زرو، سپينو زرو، زېړو، اوسپنې، کاڼو او د لرګو د څيزونو په جوړولو باندې پوهيږى. هغه د آسمانى رنګ، کاسنى او سور رنګ او د لټې د کپړې په کار پوهيږى. هغه هر قِسم پاخۀ ليکل کولے شى او چې هغۀ له هر څنګه نقشه ورکړے شى نو په هغې عمل کولے شى. هغه پرېږده چې ستا د تکړه کاريګرو سره او د هغوئ سره کار وکړى چا چې ستا د پلار يعنې د داؤد بادشاه دپاره کار کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10481, '2 Chronicles 2:15', '2 Chronicles', 2, 15, '&nbsp;نو اوس مونږ له هغه غنم، اوربشې، مے او د زيتُونو تېل راولېږه چې تا يې وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10482, '2 Chronicles 2:16', '2 Chronicles', 2, 16, '&nbsp;د لبنان په غرونو کښې به مونږ هغه ټول د دِيار لرګى ووهو چې تا ته يې ضرورت دے، هغه به د يو بل سره د کشتۍ په شان وتړُو او په سمندر کښې به يې روان کړُو چې تر يافا پورې ورسيږى. د هغه ځائ نه يې تۀ يروشلم ته وړلے شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10483, '2 Chronicles 2:17', '2 Chronicles', 2, 17, '&nbsp;سليمان بادشاه د هغه ټولو مسافرو مردم‌شمارى وکړه چې هغوئ د بنى اِسرائيل په مُلک کښې اوسېدل، هم هغه شان مردم‌شمارى څنګه چې د هغۀ پلار داؤد اخستې وه. هلته يو لاک درې پنځوس زره او شپږ سوه مسافر اوسېدونکى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10484, '2 Chronicles 2:18', '2 Chronicles', 2, 18, '&nbsp;هغۀ اويا زره کسان د سامان د وړلو راوړلو دپاره او اتيا زره کسان يې په غرونو کښې د کاڼو پرې کولو دپاره مقرر کړل او درې زره او شپږ سوه مشران يې د دې دپاره مقرر کړل چې د خلقو نه کار اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10485, '2 Chronicles 3:1', '2 Chronicles', 3, 1, '&nbsp;نو سليمان په يروشلم کښې د مورياه په غر د مالِک خُدائ د کور جوړول شروع کړل، چرته چې مالِک خُدائ د هغۀ پلار داؤد ته راڅرګند شوے وو. د مالِک خُدائ کور د اُرنان يبوسى په درمند جوړ شو، کوم ځائ چې داؤد خوښ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10486, '2 Chronicles 3:2', '2 Chronicles', 3, 2, '&nbsp;او د هغې جوړېدل د هغۀ د بادشاهۍ د څلورم کال د دوېمې مياشتې په دوېمه ورځ شروع شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10487, '2 Chronicles 3:3', '2 Chronicles', 3, 3, '&nbsp;سليمان چې د خُدائ پاک د کور کوم بنياد کېښودو هغه تقريباً دېرش ګزه اوږد او تقريباً لس ګزه پلن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10488, '2 Chronicles 3:4', '2 Chronicles', 3, 4, '&nbsp;د ننوتلو کوټه د کور د پوره پلنوالى هومره يعنې تقريباً لس ګزه وه او تقريباً شپېتۀ ګزه اوچته وه. د کوټې دننه دېوالونه او چت په سوچه سرو زرو باندې پټ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10489, '2 Chronicles 3:5', '2 Chronicles', 3, 5, '&nbsp;په لويه کوټه باندې د دِيار د لرګى تختې لګولے شوې وې چې په سوچه سرو زرو باندې پټې وې، چې په دې باندې د کجورو د ونو ګُلکارى شوې وه او د زنځيرونو نمونې ورباندې جوړې شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10490, '2 Chronicles 3:6', '2 Chronicles', 3, 6, '&nbsp;بادشاه د خُدائ پاک کور د قيمتى کاڼو او د پروائم د مُلک د سرو زرو سره ښائسته کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10491, '2 Chronicles 3:7', '2 Chronicles', 3, 7, '&nbsp;هغۀ د کور د دېوالونو، د تختو او دروازو پټولو دپاره سرۀ زر استعمال کړل، کاريګرو په دېوالونو باندې د وزرو والا مخلوق نقشې هم جوړې کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10492, '2 Chronicles 3:8', '2 Chronicles', 3, 8, '&nbsp;د دنننۍ کوټې نوم زيات مقدس ځائ وو، چې تقريباً لس ګزه اوږده او لس ګزه پلنه وه، چې د کور د پوره پلنوالى هومره وه. د زيات مقدس ځائ د دېوالونو پټولو دپاره د شلو ټنو نه زيات سرۀ زر استعمال شوى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10493, '2 Chronicles 3:9', '2 Chronicles', 3, 9, '&nbsp;تقريباً نيم سېر سرۀ زر د مېخونو د جوړولو دپاره استعمال شوى وُو او د برنو کوټو دېوالونه هم په سرو زرو باندې پټ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10494, '2 Chronicles 3:10', '2 Chronicles', 3, 10, '&nbsp;بادشاه خپلو کاريګرو له دا حُکم هم ورکړو چې د وزرو والا مخلوق د اوسپنې نه جوړ کړئ، په سرو زرو يې پټ کړئ او په زيات مقدس ځائ کښې يې کېږدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10495, '2 Chronicles 3:14', '2 Chronicles', 3, 14, '&nbsp;د زيات مقدس ځائ يوه پرده د مهينې لټې نه جوړه وه، چې د آسمانى، کاسنى او سور رنګ د وزرو والا مخلوق د شکلونو کار ورباندې شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10496, '2 Chronicles 3:15', '2 Chronicles', 3, 15, '&nbsp;بادشاه دوه ستنې جوړې کړې چې هره يوه تقريباً اوولس ګزه لوړه وه او د خُدائ پاک د کور په مخکښې يې ولګولې. د هرې ستنې دپاسه تقريباً درې ګزه لوړ تاجونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10497, '2 Chronicles 3:16', '2 Chronicles', 3, 16, '&nbsp;د ستنو سرونه د زنځيرونو د کَړو په شکلونو او په سلو انارو باندې ښائسته کړے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10498, '2 Chronicles 3:17', '2 Chronicles', 3, 17, '&nbsp;ستنې د خُدائ پاک د کور د ننوتلو په طرفونو باندې لګولے شوې وې، د جنوب په طرف باندې چې کومه ستنه لګولے شوې وه د هغې نوم يکين وو او چې په شمالى طرف باندې وه د هغې نوم بوعز وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10499, '2 Chronicles 4:1', '2 Chronicles', 4, 1, '&nbsp;د سليمان بادشاه يوه د زېړو قربان‌ګاه وه، کومه چې تقريباً لس ګزه اوږده، لس ګزه پلنه او پينځۀ ګزه اوچته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10500, '2 Chronicles 4:2', '2 Chronicles', 4, 2, '&nbsp;هغۀ د زېړو يوه ګول ډيګۍ هم جوړه کړه چې تقريباً درې ګزه ډُوبه وه، مينځ يې پينځۀ ګزه وو او پينځلس ګزه غټه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');